// Why Code: groups spec values across the range and builds the prompt; it would take a dozen Set and Aggregate nodes.
const s = $('Write settings').first().json;
const picks = $('Anything to write?').all().map(i => i.json);
const cols = $('Read the collection').all().map(i => i.json.data?.collection);
const skip = new Set(s.skip_spec_keys || []);
const label = k => k.replace(/_/g, ' ').replace(/^./, c => c.toUpperCase());
const show = v => { try { const j = JSON.parse(v); if (Array.isArray(j)) return j.join(', '); if (j && typeof j === 'object') return j.value != null ? `${j.value}${j.unit ? ' ' + j.unit.toLowerCase() : ''}` : ''; } catch (e) {} return String(v); };
const SYSTEM = `You write short buyer's guides for collection pages at ${s.store_name}. ${s.voice}
- Help the shopper choose: what matters, what the trade-offs are, which spec suits which job.
- Every feature, spec, number or capability you mention must appear in SPECS. If it isn't there, leave it out. General advice about what a spec means is fine; claims about these products are not.
- Talk about types of product and specs, never a specific model, and never recommend one product.
- No fear selling, no filler openers, no empty superlatives, no em dashes.`;
return picks.map((p, i) => {
  const c = cols[i];
  const products = (c?.products?.nodes || []).filter(x => x.status === 'ACTIVE');
  const base = { gid: p.gid, handle: p.handle, title: p.title, keyword: p.keyword, volume: p.volume, live: products.length };
  if (!c || products.length < s.min_products) return { json: { ...base, ok: false, reason: `only ${products.length} live products` } };
  const tally = {};
  const perProduct = products.slice(0, 25).map(x => {
    const specs = (x.metafields?.nodes || []).filter(m => !skip.has(m.key) && !/^gid:\/\//.test(m.value)).map(m => [label(m.key), show(m.value)]).filter(([, v]) => v && v.length < 200);
    for (const [k, v] of specs) { tally[k] = tally[k] || {}; tally[k][v] = (tally[k][v] || 0) + 1; }
    return `[${x.title}]\n` + specs.map(([k, v]) => `- ${k}: ${v}`).join('\n');
  });
  const common = Object.entries(tally).flatMap(([k, vals]) => Object.entries(vals).map(([v, n]) => ({ k, v, n }))).filter(x => x.n >= 2).sort((a, b) => b.n - a.n).slice(0, 30).map(x => `- ${x.k}: ${x.v} (${x.n} products)`);
  const serp = $('People also ask').all()[i]?.json?.tasks?.[0]?.result?.[0]?.items || [];
  const asked = [...new Set([...serp.filter(x => x.type === 'people_also_ask').flatMap(x => (x.items || []).map(q => q.title)), ...serp.filter(x => x.type === 'related_searches').flatMap(x => x.items || []).filter(q => typeof q === 'string')])].filter(Boolean).slice(0, 12);
  const vendors = [...new Set(products.map(x => x.vendor).filter(Boolean))];
  const prompt = `COLLECTION: ${c.title}\nKeyword: ${p.keyword}\nLive products: ${products.length}\nBRANDS: ${vendors.join(', ') || '(none)'}\n\nSPECS SHARED ACROSS THE RANGE\n${common.join('\n') || '(none)'}\n\nSPECS PER PRODUCT\n${perProduct.join('\n\n')}\n\nWHAT SHOPPERS ASK GOOGLE\n${asked.map(q => '- ' + q).join('\n') || '(nothing found)'}\nUse these to choose the section headings, where the specs above can answer them.\n\nWrite a buyer's guide in 3 or 4 sections, 250 to 400 words in total. Each section: a short heading (a question or a plain phrase), 1 or 2 short paragraphs, and optionally up to 4 bullets.\nReturn only JSON: {"sections": [{"heading": "...", "paragraphs": ["..."], "bullets": ["..."]}]}`;
  return { json: { ...base, ok: true, system: SYSTEM, prompt, questions: asked, context: [common.join('\n'), perProduct.join('\n')].join('\n'), products: products.map(x => x.title), vendors } };
});

// Why Code: parses the model's JSON (fenced or not), builds the HTML and checks numbers and names against the specs.
const ins = $('Enough products?').all().map(i => i.json);
const esc = t => String(t).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const fix = t => String(t || '').replace(/\s*[—–]\s*/g, ', ').replace(/[‘’]/g, "'").replace(/\s+/g, ' ').trim();
return $input.all().map((it, i) => {
  const p = ins[i];
  const base = { gid: p.gid, handle: p.handle, title: p.title, keyword: p.keyword, volume: p.volume, questions: p.questions, model: $('Write settings').first().json.model };
  let txt = it.json.text ?? it.json.response ?? (typeof it.json === 'object' && it.json.sections ? JSON.stringify(it.json) : '');
  txt = String(txt || '').replace(/<think>[\s\S]*?<\/think>/g, '').replace(/```(json)?/g, '').trim();
  let d = null; try { d = JSON.parse(txt.slice(txt.indexOf('{'), txt.lastIndexOf('}') + 1)); } catch (e) {}
  const secs = (d?.sections || []).map(s => ({ heading: fix(s.heading), paragraphs: (s.paragraphs || []).map(fix).filter(Boolean), bullets: (s.bullets || []).map(fix).filter(Boolean).slice(0, 4) })).filter(s => s.heading && s.paragraphs.length);
  if (!secs.length) return { json: { ...base, ok: false, error: it.json.error ? 'model call failed' : 'no guide in the reply' } };
  const plain = secs.map(s => [s.heading, ...s.paragraphs, ...s.bullets].join(' ')).join(' ');
  const words = plain.split(/\s+/).filter(Boolean).length;
  const flags = [];
  const ctx = (p.context + ' ' + p.title + ' ' + p.keyword).replace(/(\d),(?=\d{3})/g, '$1');
  const nums = [...new Set(plain.replace(/(\d),(?=\d{3})/g, '$1').match(/\d+(?:\.\d+)?/g) || [])].filter(n => !ctx.includes(n));
  if (nums.length) flags.push('numbers not in the specs: ' + nums.join(', '));
  const named = (p.products || []).filter(t => t.length > 6 && plain.toLowerCase().includes(t.toLowerCase()));
  if (named.length) flags.push('names a product: ' + named.slice(0, 3).join(', '));
  if (words < 200 || words > 480) flags.push(`${words} words`);
  const html = secs.map(s => `<h3>${esc(s.heading)}</h3>` + s.paragraphs.map(x => `<p>${esc(x)}</p>`).join('') + (s.bullets.length ? '<ul>' + s.bullets.map(x => `<li>${esc(x)}</li>`).join('') + '</ul>' : '')).join('');
  const text = secs.map(s => `*${s.heading}*\n` + s.paragraphs.join('\n') + (s.bullets.length ? '\n' + s.bullets.map(b => '• ' + b).join('\n') : '')).join('\n\n');
  return { json: { ...base, ok: true, html, text, words, flags: flags.join('; ') } };
});

// Why Code: the signature needs the exact raw body, kept as binary.
const raw = (await this.helpers.getBinaryDataBuffer(0, 'data')).toString('utf8');
const h = $input.first().json.headers;
if (Math.abs(Date.now() / 1000 - Number(h['x-slack-request-timestamp'])) > 300) throw new Error('Stale request');
const field = raw.split('&').find(kv => kv.startsWith('payload=')) || '';
const p = JSON.parse(decodeURIComponent(field.slice(8).replace(/\+/g, ' ')));
const a = p.actions[0];
let v = {}; try { v = JSON.parse(a.value); } catch (e) {}
return [{ json: { base: `v0:${h['x-slack-request-timestamp']}:${raw}`, expected: h['x-slack-signature'],
  action: a.action_id, collection_id: v.c, revision: Number(v.r), user: p.user?.username || p.user?.name || p.user?.id, channel: p.channel?.id, ts: p.message?.ts, blocks: p.message?.blocks || [] } }];

// Why Code: one decision record from three paths (published, refused, redraft or skip), for one save and one card update.
const c = $('Read the click').first().json;
const g = $('Get the guide').first().json;
const store = $('Review settings').first().json.store_domain;
if (c.action === 'guide_approve') {
  const errs = $input.first().json.data?.metafieldsSet?.userErrors || [];
  const err = $input.first().json.error ? String($input.first().json.error.message || $input.first().json.error) : errs.map(e => e.message).join('; ');
  return [{ json: { status: err ? 'review' : 'live', error: err || null, note: err ? `:x: Shopify refused it: ${err}` : `:white_check_mark: Approved by @${c.user}. Live on <https://${store}/collections/${g.handle}|the collection page>.` } }];
}
if (c.action === 'guide_redraft') return [{ json: { status: 'redraft', error: null, note: `:repeat: @${c.user} asked for a redraft. It's redrafted on the next run.` } }];
return [{ json: { status: 'skipped', error: null, note: `:heavy_minus_sign: Skipped by @${c.user}.` } }];
